    60  SplashFTFont::SplashFTFont(SplashFTFontFile *fontFileA, SplashCoord *matA,
    61                             SplashCoord *textMatA):
    62    SplashFont(fontFileA, matA, textMatA, fontFileA->engine->aa),
    63    enableFreeTypeHinting(fontFileA->engine->enableFreeTypeHinting),
    64    enableSlightHinting(fontFileA->engine->enableSlightHinting)
    65  {
    66    FT_Face face;
    67    int div;
    68    int x, y;
    69  #ifdef USE_FIXEDPOINT
    70    SplashCoord scale;
    71  #endif
    72
    73    face = fontFileA->face;
    74    if (FT_New_Size(face, &sizeObj)) {
    75      return;
    76    }
    77    face->size = sizeObj;
    78    size = splashRound(splashDist(0, 0, mat[2], mat[3]));
    79    if (size < 1) {
    80      size = 1;
    81    }
    82    if (FT_Set_Pixel_Sizes(face, 0, size)) {
    83      return;
    84    }
    85    // if the textMat values are too small, FreeType's fixed point
    86    // arithmetic doesn't work so well
    87    textScale = splashDist(0, 0, textMat[2], textMat[3]) / size;
    88
    89    if (unlikely(textScale == 0)) {
    90      return;
    91    }
    92
    93    div = face->bbox.xMax > 20000 ? 65536 : 1;
    94
    95  #ifdef USE_FIXEDPOINT
    96    scale = (SplashCoord)1 / (SplashCoord)face->units_per_EM;
    97
    98    // transform the four corners of the font bounding box -- the min
    99    // and max values form the bounding box of the transformed font
   100    x = (int)(mat[0] * (scale * (face->bbox.xMin / div)) +
   101              mat[2] * (scale * (face->bbox.yMin / div)));
   102    xMin = xMax = x;
   103    y = (int)(mat[1] * (scale * (face->bbox.xMin / div)) +
   104              mat[3] * (scale * (face->bbox.yMin / div)));
   105    yMin = yMax = y;
   106    x = (int)(mat[0] * (scale * (face->bbox.xMin / div)) +
   107              mat[2] * (scale * (face->bbox.yMax / div)));
   108    if (x < xMin) {
   109      xMin = x;
   110    } else if (x > xMax) {
   111      xMax = x;
   112    }
   113    y = (int)(mat[1] * (scale * (face->bbox.xMin / div)) +
   114              mat[3] * (scale * (face->bbox.yMax / div)));
   115    if (y < yMin) {
   116      yMin = y;
   117    } else if (y > yMax) {
   118      yMax = y;
   119    }
   120    x = (int)(mat[0] * (scale * (face->bbox.xMax / div)) +
   121              mat[2] * (scale * (face->bbox.yMin / div)));
   122    if (x < xMin) {
   123      xMin = x;
   124    } else if (x > xMax) {
   125      xMax = x;
   126    }
   127    y = (int)(mat[1] * (scale * (face->bbox.xMax / div)) +
   128              mat[3] * (scale * (face->bbox.yMin / div)));
   129    if (y < yMin) {
   130      yMin = y;
   131    } else if (y > yMax) {
   132      yMax = y;
   133    }
   134    x = (int)(mat[0] * (scale * (face->bbox.xMax / div)) +
   135              mat[2] * (scale * (face->bbox.yMax / div)));
   136    if (x < xMin) {
   137      xMin = x;
   138    } else if (x > xMax) {
   139      xMax = x;
   140    }
   141    y = (int)(mat[1] * (scale * (face->bbox.xMax / div)) +
   142              mat[3] * (scale * (face->bbox.yMax / div)));
   143    if (y < yMin) {
   144      yMin = y;
   145    } else if (y > yMax) {
   146      yMax = y;
   147    }
   148  #else // USE_FIXEDPOINT
   149    // transform the four corners of the font bounding box -- the min
   150    // and max values form the bounding box of the transformed font
   151    x = (int)((mat[0] * face->bbox.xMin + mat[2] * face->bbox.yMin) /
   152              (div * face->units_per_EM));
   153    xMin = xMax = x;
   154    y = (int)((mat[1] * face->bbox.xMin + mat[3] * face->bbox.yMin) /
   155              (div * face->units_per_EM));
   156    yMin = yMax = y;
   157    x = (int)((mat[0] * face->bbox.xMin + mat[2] * face->bbox.yMax) /
   158              (div * face->units_per_EM));
   159    if (x < xMin) {
   160      xMin = x;
   161    } else if (x > xMax) {
   162      xMax = x;
   163    }
   164    y = (int)((mat[1] * face->bbox.xMin + mat[3] * face->bbox.yMax) /
   165              (div * face->units_per_EM));
   166    if (y < yMin) {
   167      yMin = y;
   168    } else if (y > yMax) {
   169      yMax = y;
   170    }
   171    x = (int)((mat[0] * face->bbox.xMax + mat[2] * face->bbox.yMin) /
   172              (div * face->units_per_EM));
   173    if (x < xMin) {
   174      xMin = x;
   175    } else if (x > xMax) {
   176      xMax = x;
   177    }
   178    y = (int)((mat[1] * face->bbox.xMax + mat[3] * face->bbox.yMin) /
   179              (div * face->units_per_EM));
   180    if (y < yMin) {
   181      yMin = y;
   182    } else if (y > yMax) {
   183      yMax = y;
   184    }
   185    x = (int)((mat[0] * face->bbox.xMax + mat[2] * face->bbox.yMax) /
   186              (div * face->units_per_EM));
   187    if (x < xMin) {
   188      xMin = x;
   189    } else if (x > xMax) {
   190      xMax = x;
   191    }
   192    y = (int)((mat[1] * face->bbox.xMax + mat[3] * face->bbox.yMax) /
   193              (div * face->units_per_EM));
   194    if (y < yMin) {
   195      yMin = y;
   196    } else if (y > yMax) {
   197      yMax = y;
   198    }
   199  #endif // USE_FIXEDPOINT
   200    // This is a kludge: some buggy PDF generators embed fonts with
   201    // zero bounding boxes.
   202    if (xMax == xMin) {
   203      xMin = 0;
   204      xMax = size;
   205    }
   206    if (yMax == yMin) {
   207      yMin = 0;
   208      yMax = (int)((SplashCoord)1.2 * size);
   209    }
   210
   211    // compute the transform matrix
   212  #ifdef USE_FIXEDPOINT
   213    matrix.xx = (FT_Fixed)((mat[0] / size).get16Dot16());
   214    matrix.yx = (FT_Fixed)((mat[1] / size).get16Dot16());
   215    matrix.xy = (FT_Fixed)((mat[2] / size).get16Dot16());
   216    matrix.yy = (FT_Fixed)((mat[3] / size).get16Dot16());
   217    textMatrix.xx = (FT_Fixed)((textMat[0] / (textScale * size)).get16Dot16());
   218    textMatrix.yx = (FT_Fixed)((textMat[1] / (textScale * size)).get16Dot16());
   219    textMatrix.xy = (FT_Fixed)((textMat[2] / (textScale * size)).get16Dot16());
   220    textMatrix.yy = (FT_Fixed)((textMat[3] / (textScale * size)).get16Dot16());
   221  #else
   222    matrix.xx = (FT_Fixed)((mat[0] / size) * 65536);
   223    matrix.yx = (FT_Fixed)((mat[1] / size) * 65536);
   224    matrix.xy = (FT_Fixed)((mat[2] / size) * 65536);
   225    matrix.yy = (FT_Fixed)((mat[3] / size) * 65536);
   226    textMatrix.xx = (FT_Fixed)((textMat[0] / (textScale * size)) * 65536);
   227    textMatrix.yx = (FT_Fixed)((textMat[1] / (textScale * size)) * 65536);
   228    textMatrix.xy = (FT_Fixed)((textMat[2] / (textScale * size)) * 65536);
   229    textMatrix.yy = (FT_Fixed)((textMat[3] / (textScale * size)) * 65536);
   230  #endif
   231  }
