   270  GBool SplashFTFont::makeGlyph(int c, int xFrac, int yFrac,
   271                                SplashGlyphBitmap *bitmap, int x0, int y0, SplashClip *clip, SplashClipResult *clipRes) {
   272    SplashFTFontFile *ff;
   273    FT_Vector offset;
   274    FT_GlyphSlot slot;
   275    FT_UInt gid;
   276    int rowSize;
   277    Guchar *p, *q;
   278    int i;
   279
   280    ff = (SplashFTFontFile *)fontFile;
   281
   282    ff->face->size = sizeObj;
   283    offset.x = (FT_Pos)(int)((SplashCoord)xFrac * splashFontFractionMul * 64);
   284    offset.y = 0;
   285    FT_Set_Transform(ff->face, &matrix, &offset);
   286    slot = ff->face->glyph;
   287
   288    if (ff->codeToGID && c < ff->codeToGIDLen && c >= 0) {
   289      gid = (FT_UInt)ff->codeToGID[c];
   290    } else {
   291      gid = (FT_UInt)c;
   292    }
   293
   294    if (FT_Load_Glyph(ff->face, gid, getFTLoadFlags(ff->type1, ff->trueType, aa, enableFreeTypeHinting, enableSlightHinting))) {
   295      return gFalse;
   296    }
   297
   298    // prelimirary values based on FT_Outline_Get_CBox
   299    // we add two pixels to each side to be in the safe side
   300    FT_BBox cbox;
   301    FT_Outline_Get_CBox(&ff->face->glyph->outline, &cbox);
   302    bitmap->x = -(cbox.xMin / 64) + 2;
   303    bitmap->y =  (cbox.yMax / 64) + 2;
   304    bitmap->w = ((cbox.xMax - cbox.xMin) / 64) + 4;
   305    bitmap->h = ((cbox.yMax - cbox.yMin) / 64) + 4;
   306
   307    *clipRes = clip->testRect(x0 - bitmap->x,
   308                              y0 - bitmap->y,
   309                              x0 - bitmap->x + bitmap->w,
   310                              y0 - bitmap->y + bitmap->h);
   311    if (*clipRes == splashClipAllOutside) {
   312      bitmap->freeData = gFalse;
   313      return gTrue;
   314    }
   315
   316    if (FT_Render_Glyph(slot, aa ? ft_render_mode_normal
   317                                 : ft_render_mode_mono)) {
   318      return gFalse;
   319    }
   320
   321    if (slot->bitmap.width == 0 || slot->bitmap.rows == 0) {
   322      // this can happen if (a) the glyph is really tiny or (b) the
   323      // metrics in the TrueType file are broken
   324      return gFalse;
   325    }
   326
   327    bitmap->x = -slot->bitmap_left;
   328    bitmap->y = slot->bitmap_top;
   329    bitmap->w = slot->bitmap.width;
   330    bitmap->h = slot->bitmap.rows;
   331    bitmap->aa = aa;
   332    if (aa) {
   333      rowSize = bitmap->w;
   334    } else {
   335      rowSize = (bitmap->w + 7) >> 3;
   336    }
   337    bitmap->data = (Guchar *)gmallocn_checkoverflow(rowSize, bitmap->h);
   338    if (!bitmap->data) {
   339      return gFalse;
   340    }
   341    bitmap->freeData = gTrue;
   342    for (i = 0, p = bitmap->data, q = slot->bitmap.buffer;
   343         i < bitmap->h;
   344         ++i, p += rowSize, q += slot->bitmap.pitch) {
   345      memcpy(p, q, rowSize);
   346    }
   347
   348    return gTrue;
   349  }
